mod common;

use common::Harness;
use serde_json::{Value, json};

fn tags(h: &mut Harness, name: &str) -> Value {
    h.ok(json!({"Command": "ListQueueTags", "QueueName": name}))["Tags"].clone()
}

fn queue() -> Harness {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h
}

fn tag(h: &mut Harness, t: Value) -> Value {
    h.run(json!({"Command": "TagQueue", "QueueName": "q", "Tags": t}))
}

#[test]
fn new_queue_has_no_tags_and_results_are_empty() {
    let mut h = queue();
    assert_eq!(tags(&mut h, "q"), json!({}));
    assert_eq!(
        tag(&mut h, json!({})),
        json!({"ok": true})
    );
    let r = h.run(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": []}));
    assert_eq!(r, json!({"ok": true}));
}

#[test]
fn tag_sets_and_replaces_and_untag_ignores_missing_keys() {
    let mut h = queue();
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "1", "B": "", "c": "x"}}));
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "2"}}));
    assert_eq!(tags(&mut h, "q"), json!({"a": "2", "B": "", "c": "x"}));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a", "zzz", "b"]}));
    assert_eq!(tags(&mut h, "q"), json!({"B": "", "c": "x"}));
}

#[test]
fn tag_validation_is_all_or_nothing() {
    let mut h = queue();
    let long_value = "é".repeat(129);
    let cases = [
        json!({"a b": "1"}),
        json!({"": "1"}),
        json!({"k".repeat(129): "1"}),
        json!({"ok": 1}),
        json!({"ok": null}),
        json!({"ok": long_value}),
    ];
    for bad in cases {
        let r = tag(&mut h, json!({"fine": "1"}));
        assert_eq!(r["ok"], true);
        let mut with_bad = bad.clone();
        with_bad["other"] = json!("x");
        assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": with_bad})), "InvalidParameterValue", "{bad}");
        assert_eq!(tags(&mut h, "q"), json!({"fine": "1"}));
    }
    assert_eq!(tag(&mut h, json!({"k".repeat(128): "é".repeat(128)}))["ok"], true);
}

#[test]
fn tag_and_untag_parameter_checks() {
    let mut h = queue();
    let run = |h: &mut Harness, v: Value| h.err(v);
    assert_eq!(run(&mut h, json!({"Command": "TagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(run(&mut h, json!({"Command": "TagQueue", "QueueName": "q", "Tags": []})), "InvalidParameterValue");
    assert_eq!(run(&mut h, json!({"Command": "TagQueue", "QueueName": "nope", "Tags": {}})), "QueueDoesNotExist");
    assert_eq!(run(&mut h, json!({"Command": "UntagQueue", "QueueName": "q"})), "MissingParameter");
    assert_eq!(run(&mut h, json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": {}})), "InvalidParameterValue");
    assert_eq!(run(&mut h, json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": [1]})), "InvalidParameterValue");
    assert_eq!(run(&mut h, json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["a b"]})), "InvalidParameterValue");
    assert_eq!(run(&mut h, json!({"Command": "UntagQueue", "QueueName": "nope", "TagKeys": []})), "QueueDoesNotExist");
    assert_eq!(run(&mut h, json!({"Command": "ListQueueTags"})), "MissingParameter");
    assert_eq!(run(&mut h, json!({"Command": "ListQueueTags", "QueueName": "nope"})), "QueueDoesNotExist");
}

fn n_tags(range: std::ops::Range<u32>) -> Value {
    Value::Object(range.map(|i| (format!("k{i}"), json!("v"))).collect())
}

#[test]
fn at_most_fifty_tags() {
    let mut h = queue();
    assert_eq!(tag(&mut h, n_tags(0..50))["ok"], true);
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"extra": "1"}})), "LimitExceeded");
    assert_eq!(tags(&mut h, "q").as_object().unwrap().len(), 50);
    // Replacing existing keys does not add tags.
    assert_eq!(tag(&mut h, json!({"k0": "new"}))["ok"], true);
    assert_eq!(h.err(json!({"Command": "TagQueue", "QueueName": "q", "Tags": n_tags(40..51)})), "LimitExceeded");
    assert_eq!(tags(&mut h, "q")["k0"], json!("new"));
    h.ok(json!({"Command": "UntagQueue", "QueueName": "q", "TagKeys": ["k0"]}));
    assert_eq!(tag(&mut h, json!({"extra": "1"}))["ok"], true);
}

#[test]
fn tags_are_not_attributes_and_survive_purge_but_not_delete() {
    let mut h = Harness::new();
    let create = json!({"Command": "CreateQueue", "QueueName": "q"});
    h.ok(create.clone());
    h.ok(json!({"Command": "TagQueue", "QueueName": "q", "Tags": {"a": "1"}}));
    let attrs = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert!(attrs["Attributes"].get("Tags").is_none());
    h.ok(create.clone());
    assert_eq!(tags(&mut h, "q"), json!({"a": "1"}));
    h.ok(json!({"Command": "SendMessage", "QueueName": "q", "Body": "x"}));
    h.ok(json!({"Command": "PurgeQueue", "QueueName": "q"}));
    assert_eq!(tags(&mut h, "q"), json!({"a": "1"}));
    h.ok(json!({"Command": "DeleteQueue", "QueueName": "q"}));
    h.ok(create);
    assert_eq!(tags(&mut h, "q"), json!({}));
}
